class Solution:
    def minimumTime(self, n: int, start: int, requests: List[List[int]]) -> int:
        m = len(requests)
        FULL = (1 << m) - 1
        INF = float('inf')
        dp = [[INF] * m for _ in range(1 << m)]
        for i, (a, f) in enumerate(requests):
            dp[1 << i][i] = max(abs(f - start), a)
        for mask in range(1 << m):
            row = dp[mask]
            for i in range(m):
                if not (mask >> i & 1) or row[i] == INF:
                    continue
                fi, ti = requests[i][1], row[i]
                for j in range(m):
                    if mask >> j & 1:
                        continue
                    t = max(ti + abs(requests[j][1] - fi), requests[j][0])
                    if t < dp[mask | 1 << j][j]:
                        dp[mask | 1 << j][j] = t
        return min(dp[FULL])

