class Solution {
public:
    long long minimumTime(int n, int start, vector<vector<int>>& requests) {
        int m = requests.size();
        int FULL = (1 << m) - 1;
        const long long INF = LLONG_MAX;
        vector<vector<long long>> dp(1 << m, vector<long long>(m, INF));
        for (int i = 0; i < m; i++)
            dp[1 << i][i] = max(abs(requests[i][1] - start), (long long)requests[i][0]);
        for (int mask = 0; mask <= FULL; mask++) {
            for (int i = 0; i < m; i++) {
                if (!(mask >> i & 1) || dp[mask][i] == INF) continue;
                for (int j = 0; j < m; j++) {
                    if (mask >> j & 1) continue;
                    long long t = max(dp[mask][i] + abs(requests[j][1] - requests[i][1]),
                                      (long long)requests[j][0]);
                    dp[mask | 1 << j][j] = min(dp[mask | 1 << j][j], t);
                }
            }
        }
        return *min_element(dp[FULL].begin(), dp[FULL].end());
    }
};

