class Solution {
    public long minimumTime(int n, int start, int[][] requests) {
        int m = requests.length;
        int FULL = (1 << m) - 1;
        long INF = Long.MAX_VALUE;
        long[][] dp = new long[1 << m][m];
        for (long[] row : dp) Arrays.fill(row, INF);
        for (int i = 0; i < m; i++)
            dp[1 << i][i] = Math.max(Math.abs(requests[i][1] - start), (long) requests[i][0]);
        for (int mask = 0; mask <= FULL; mask++) {
            for (int i = 0; i < m; i++) {
                if ((mask >> i & 1) == 0 || dp[mask][i] == INF) continue;
                for (int j = 0; j < m; j++) {
                    if ((mask >> j & 1) != 0) continue;
                    long t = Math.max(dp[mask][i] + Math.abs(requests[j][1] - requests[i][1]),
                                      (long) requests[j][0]);
                    int nm = mask | (1 << j);
                    if (t < dp[nm][j]) dp[nm][j] = t;
                }
            }
        }
        long ans = INF;
        for (long v : dp[FULL]) ans = Math.min(ans, v);
        return ans;
    }
}

