            for (let j = 0; j < m; j++) {
                if (mask >> j & 1) continue;
                const t = Math.max(dp[mask][i] + Math.abs(requests[j][1] - requests[i][1]),
                                   requests[j][0]);
                if (t < dp[mask | (1 << j)][j]) dp[mask | (1 << j)][j] = t;
            }
        }
    }
    return Math.min(...dp[FULL]);
