class Solution:
    def minimumTime(self, n: int, start: int, requests: List[List[int]]) -> int:
        import functools
        m = len(requests)
        FULL = (1 << m) - 1
        INF = float('inf')
        @functools.lru_cache(maxsize=None)
        def solve(mask, last):
            if mask == (1 << last):
                return max(abs(requests[last][1] - start), requests[last][0])
            pm = mask ^ (1 << last)
            best = INF
            for i in range(m):
                if pm >> i & 1:
                    cand = max(requests[last][0],
                               solve(pm, i) + abs(requests[last][1] - requests[i][1]))
                    best = min(best, cand)
            return best
        return min(solve(FULL, i) for i in range(m))

