class Solution {
    int m;
    vector<vector<int>> rq;
    int st;
    vector<vector<long long>> memo;
    long long solve(int mask, int last) {
        if (mask == (1 << last))
            return max(abs(rq[last][1] - st), (long long)rq[last][0]);
        long long& res = memo[mask][last];
        if (res != -1) return res;
        int pm = mask ^ (1 << last);
        long long best = LLONG_MAX;
        for (int i = 0; i < m; i++) {
            if (pm >> i & 1) {
                long long cand = max((long long)rq[last][0],
                                     solve(pm, i) + (long long)abs(rq[last][1] - rq[i][1]));
                best = min(best, cand);
            }
        }
        return res = best;
    }
public:
    long long minimumTime(int n, int start, vector<vector<int>>& requests) {
        m = requests.size(); rq = requests; st = start;
        memo.assign(1 << m, vector<long long>(m, -1));
        int FULL = (1 << m) - 1;
        long long ans = LLONG_MAX;
        for (int i = 0; i < m; i++) ans = min(ans, solve(FULL, i));
        return ans;
    }
};

