                best = Math.min(best, cand);
            }
        }
        return memo[mask][last] = best;
    }
    public long minimumTime(int n, int start, int[][] requests) {
        m = requests.length; rq = requests; st = start;
        memo = new long[1 << m][m];
        for (long[] row : memo) Arrays.fill(row, -1);
        int FULL = (1 << m) - 1;
        long ans = Long.MAX_VALUE;
        for (int i = 0; i < m; i++) ans = Math.min(ans, solve(FULL, i));
        return ans;
    }
}

