var minimumTime = function(n, start, requests) {
    const m = requests.length;
    const memo = new Map();
    const solve = (mask, last) => {
        if (mask === (1 << last))
            return Math.max(Math.abs(requests[last][1] - start), requests[last][0]);
        const key = mask * 32 + last;
        if (memo.has(key)) return memo.get(key);
        const pm = mask ^ (1 << last);
        let best = Infinity;
        for (let i = 0; i < m; i++) {
            if (pm >> i & 1) {
                best = Math.min(best,
                    Math.max(requests[last][0],
                             solve(pm, i) + Math.abs(requests[last][1] - requests[i][1])));
            }
        }
        memo.set(key, best);
        return best;
    };
    const FULL = (1 << m) - 1;
    let ans = Infinity;
    for (let i = 0; i < m; i++) ans = Math.min(ans, solve(FULL, i));
    return ans;
};
